from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])

    def mode(values):
        return Counter(values).most_common(1)[0][0]

    # Detect repeated divider rows and columns from their dominant colors.
    row_modes = [mode(row) for row in grid]
    panel_color = mode(row_modes)
    separator_rows = [r for r, color in enumerate(row_modes) if color != panel_color]
    if len(separator_rows) < 2:
        return [row[:] for row in grid]

    row_set = set(separator_rows)
    body_rows = [r for r in range(h) if r not in row_set]
    separator_cols = [c for c in range(w)
                      if mode([grid[r][c] for r in body_rows]) != panel_color]
    if len(separator_cols) < 2:
        return [row[:] for row in grid]

    col_set = set(separator_cols)
    background = mode([grid[r][c] for r in body_rows for c in range(w)
                       if c not in col_set])
    separator_color = mode([row_modes[r] for r in separator_rows])

    # A cell between adjacent divider intersections is a symbol only when the
    # four corners agree on the same non-background, non-divider color.
    output = []
    for r1, r2 in zip(separator_rows, separator_rows[1:]):
        row = []
        for c1, c2 in zip(separator_cols, separator_cols[1:]):
            corners = (grid[r1][c1], grid[r1][c2], grid[r2][c1], grid[r2][c2])
            if (len(set(corners)) == 1 and
                    corners[0] not in (background, separator_color)):
                row.append(corners[0])
            else:
                row.append(background)
        output.append(row)

    # Blank intervals that extend the lattice beyond its encoded content are
    # padding; retain all background cells within the nonblank bounding box.
    while len(output) > 1 and all(v == background for v in output[0]):
        output.pop(0)
    while len(output) > 1 and all(v == background for v in output[-1]):
        output.pop()
    while output and len(output[0]) > 1 and all(row[0] == background for row in output):
        for row in output:
            row.pop(0)
    while output and len(output[0]) > 1 and all(row[-1] == background for row in output):
        for row in output:
            row.pop()
    return output


